
import { formatCurrency } from '@game-studio/utilities';
import { inversifyContainer } from '../inversify/container';

export interface ICurrencyFormatter {
    rounded: (subunits: number) => string;
    precise: (subunits: number, returnSubunit?: boolean) => string;
    dynamicPrecision: (subunits: number, wholeFigures: number, returnSubunit?: boolean) => string;
}

export class CurrencyFormatter implements ICurrencyFormatter {

    private returnSubUnits: boolean;

    constructor(returnSubUnits: boolean) {
        this.returnSubUnits = returnSubUnits;
    }

    public rounded(subunits: number): string {

        const settings = Object.assign({}, inversifyContainer.currencySettings);
        settings.precision = 0;
        return formatCurrency(subunits, settings);
    }

    public precise(subunits: number, returnSubunit: boolean = this.returnSubUnits): string {
        return formatCurrency(subunits, inversifyContainer.currencySettings, returnSubunit);
    }

    public dynamicPrecision(subunits: number, wholeFigures: number, returnSubunit?: boolean): string {
        if (subunits >= Math.pow(10, wholeFigures + 2)) {
            return this.rounded(subunits);
        } else {
            return this.precise(subunits, returnSubunit);
        }
    }
}
